alter policy "fleet_dispatch_signal_policy_insert" on public.fleet_dispatch_signal_policies with check (exists (select 1 from public.app_business_memberships bm where bm.business_id = fleet_dispatch_signal_policies.business_id and bm.user_id = (select auth.uid()) and (bm.role)::text = any (array['owner'::text,'admin'::text,'manager'::text])));
alter policy "fleet_dispatch_signal_policy_update" on public.fleet_dispatch_signal_policies using (exists (select 1 from public.app_business_memberships bm where bm.business_id = fleet_dispatch_signal_policies.business_id and bm.user_id = (select auth.uid()) and (bm.role)::text = any (array['owner'::text,'admin'::text,'manager'::text]))) with check (exists (select 1 from public.app_business_memberships bm where bm.business_id = fleet_dispatch_signal_policies.business_id and bm.user_id = (select auth.uid()) and (bm.role)::text = any (array['owner'::text,'admin'::text,'manager'::text])));
alter policy "business members can read intelligence actions" on public.intelligence_action_links using (business_id is null or exists (select 1 from public.business_members bm where bm.business_id = intelligence_action_links.business_id and bm.user_id = (select auth.uid())));
alter policy "business members can update intelligence actions" on public.intelligence_action_links using (business_id is null or exists (select 1 from public.business_members bm where bm.business_id = intelligence_action_links.business_id and bm.user_id = (select auth.uid())));
alter policy "admins manage location quality reviews" on public.location_quality_reviews using (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and (p.role = 'admin'::account_role or p.is_admin = true))) with check (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and (p.role = 'admin'::account_role or p.is_admin = true)));
alter policy "qr_intelligence_events_own_read" on public.qr_intelligence_events using (user_id = (select auth.uid()));
alter policy "reporting_runs_scoped_select" on public.reporting_runs using (exists (select 1 from public.reporting_schedules s where s.id = reporting_runs.schedule_id and (s.owner_id = (select auth.uid()) or is_platform_owner((select auth.uid())) or exists (select 1 from public.business_members bm where bm.business_id = s.scope_id and bm.user_id = (select auth.uid())))));
alter policy "reporting_schedules_owner_delete" on public.reporting_schedules using (owner_id = (select auth.uid()) or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and (p.is_admin or p.is_platform_owner)));
alter policy "reporting_schedules_owner_insert" on public.reporting_schedules with check (owner_id = (select auth.uid()) or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and (p.is_admin or p.is_platform_owner)));
alter policy "reporting_schedules_scoped_select" on public.reporting_schedules using (owner_id = (select auth.uid()) or is_platform_owner((select auth.uid())) or (scope_type = 'business'::text and exists (select 1 from public.business_members bm where bm.business_id = reporting_schedules.scope_id and bm.user_id = (select auth.uid()))));
alter policy "reporting_schedules_scoped_update" on public.reporting_schedules using (owner_id = (select auth.uid()) or is_platform_owner((select auth.uid())) or (scope_type = 'business'::text and exists (select 1 from public.business_members bm where bm.business_id = reporting_schedules.scope_id and bm.user_id = (select auth.uid()) and lower((bm.role)::text) = any (array['owner'::text,'admin'::text,'manager'::text,'fleet_owner'::text,'fleet_manager'::text,'enterprise_owner'::text,'enterprise_admin'::text,'enterprise_manager'::text])))) with check (owner_id = (select auth.uid()) or is_platform_owner((select auth.uid())) or (scope_type = 'business'::text and exists (select 1 from public.business_members bm where bm.business_id = reporting_schedules.scope_id and bm.user_id = (select auth.uid()) and lower((bm.role)::text) = any (array['owner'::text,'admin'::text,'manager'::text,'fleet_owner'::text,'fleet_manager'::text,'enterprise_owner'::text,'enterprise_admin'::text,'enterprise_manager'::text]))));
alter policy "review_moderation_actions_admin_select" on public.review_moderation_actions using (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.is_admin = true));
